// agent-qa — fake-provider DataEnvelopes for every MD-1 v1 kind and every SC-1 kind (test-only module).
//
// The JSON beside this file is GENERATED by tests/test_uct_agent_qa_fixtures.py (the single authority, and the
// Python rail that keeps these files current). Do not hand-edit a JSON file here; regenerate:
//     C:\UCT\agent\.venv\Scripts\python.exe -m tests.test_uct_agent_qa_fixtures --write
//
//   import { loadFixture, casesFor, KINDS, CASES } from '../__fixtures__/program'
//   const env = loadFixture('quote', 'market-closed')        // a deep copy; mutate freely
//
// Per-kind `data` shapes are PROVISIONAL until agent-md documents them (MD-1 §4); the envelope follows MD-1 §3
// and the SC-1 `data` shapes follow SC-1 §2.
import index from './index.json'

const files = import.meta.glob('./envelopes/*.json', { eager: true, import: 'default' })

export const VERSION = index.version
export const CASES = Object.freeze([...index.cases])
export const KINDS = Object.freeze(Object.fromEntries(Object.entries(index.kinds).map(([k, v]) => [k, Object.freeze({ ...v })])))

function file(kind) {
  const meta = KINDS[kind]
  if (!meta) throw new Error(`no fixtures for kind ${JSON.stringify(kind)}`)
  const f = files[`./${meta.file}`]
  if (!f) throw new Error(`fixture file missing for ${kind}: ${meta.file}`)
  return f
}

export function casesFor(kind) {
  return [...(KINDS[kind]?.cases || [])]
}

/** A deep copy of one fixture envelope. `kase` defaults to the kind's declared class. */
export function loadFixture(kind, kase) {
  const c = kase || KINDS[kind]?.default_case
  const cases = file(kind).cases
  if (!(c in cases)) throw new Error(`kind ${kind} has no ${JSON.stringify(c)} fixture; it has ${Object.keys(cases).join(', ')}`)
  return structuredClone(cases[c])
}

export function allFixtures() {
  return Object.keys(KINDS).flatMap(kind => casesFor(kind).map(c => [kind, c, loadFixture(kind, c)]))
}
